-- 카탈로그에 대응이 없는 seed 작품 16개를 목록에서 숨긴다(지우지 않음).
UPDATE pieces piece
SET piece.hidden_reason = 'catalog_unmatched'
WHERE piece.composer_id = 20 AND piece.origin = 'seed' AND piece.hidden_reason IS NULL
  AND piece.id IN (
    7752, 7843, 7887, 8210, 8533, 8541, 8985, 9057, 9243, 9363, 9426, 9519, 9665, 10835, 10915, 10946
  )
  AND NOT EXISTS (SELECT 1 FROM performance_sectors sector WHERE sector.piece_id = piece.id)
  AND NOT EXISTS (SELECT 1 FROM piece_parts linking WHERE linking.linked_piece_id = piece.id);
